\begin{equation}
\label{pro:ori}
    \min_{x \in \mathcal{X}}\; F(x):=\EE_{\xi}\Big[f_\xi\Big({\EE_{\eta|\xi}[g_\eta(x,\xi)]}\Big)\Big].
\end{equation}

Here $\mathcal{X}$ is the domain of the decision variable $x\in\RR^d$; $f_\xi(\cdot):\RR^k\to\RR$ is a continuous cost function dependent on the random vector $\xi$, and $g_\eta(\cdot,\xi):\RR^d\to\RR^k$  is a vector-valued continuous cost function dependent on both random vectors $\xi$ and $\eta$. The inner expectation is with respect to $\eta$ given $\xi$, and the outer expectation is with respect to $\xi$. Similar to the classical stochastic optimization, we do not assume any knowledge on the underlying distribution of $\PP(\xi)$ nor the conditional distribution $\PP(\eta|\xi)$.  Instead, we assume availability of  samples  from the distribution $\PP(\xi)$ and samples from the conditional distribution $\PP(\eta|\xi)$ for any given $\xi$.


\begin{equation}
\label{pro:cosaa0}
   \min_{x \in \mathcal{X}}\; \hat F_{nm}(x):= \frac{1}{n}\sum_{i=1}^n f_{\xi_i}\bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{ij}}(x, \xi_{i})\bigg),
\end{equation}

where  $\{\xi_i\}_{i=1}^n$ are i.i.d. samples generated from $\PP(\xi)$ and $\{\eta_{ij}\}_{j=1}^m$ are i.i.d. samples generated from the conditional distribution $\PP(\eta | \xi_i)$ for a given outer sample $\xi_i$.  We would like to examine the total number of samples $T=nm+n$ required for SAA~(\ref{pro:cosaa0}) to achieve an $\epsilon$-optimal solution to the original CSO problem~(\ref{pro:ori}).


For convenience, we collect here some notations that will be used throughout the paper. We also introduce some  mathematical tools and propositions that are necessary for future discussion. For simplicity, we restrict our attention to $l_2$-norm, denoted as $\norm{\cdot}_2$. Similar results on sample complexity with respect to different norms can be obtained with minor modification of the analysis.


A function $f: \mathcal{X} \rightarrow \RR$ is said to be $L$-Lipschitz continuous, if there exists a constant $L>0$ such that $|f(x_1) - f(x_2)|\leq L\norm{x_1-x_2}_2, \forall x_1, x_2 \in \mathcal{X}$. The function $f: \mathcal{X} \rightarrow \RR$ is said to be $S$-Lipschitz smooth, if it is continuously differentiable and its gradient is $S$-Lipschitz continuous. This also implies that  $\forall x_1, x_2 \in \mathcal{X}:|f(x_1)-f(x_2) -\nabla f(x_2)^\top(x_1-x_2)|  \leq  \frac{S}{2}\norm{x_1-x_2}_2^2$. If a continuously differentiable function $f: \mathcal{X} \rightarrow \RR$ satisfies that $\forall x_1, x_2 \in \mathcal{X}$, $f(x_1)-f(x_2)- \nabla f(x_2)^\top(x_1-x_2) \geq \frac{\mu}{2}\norm{x_1-x_2}_2^2,$ 
then $f$ is called $\mu$-strongly convex when $\mu>0$, convex when $\mu=0$, and $\mu$-weakly convex when $\mu<0$.


\begin{defn}[H\"olderian error bound  condition]
\label{def:lineq}
Let $f: \mathcal{X} \rightarrow \RR$ be a function with compact domain $\mathcal{X}$ and the optimal solution set $\mathcal{X}^*$ is nonempty. $f(\cdot)$ satisfies the $(\mu,\delta)$-H\"olderian error bound condition if there exists $\delta \geq 0$ and $\mu>0$ such that 
\begin{equation*}
\forall x\in \mathcal{X}, \quad f(x)-\min_{x\in\mathcal{X}}f(x) \geq \mu \inf_{z\in\mathcal{X}^*}\norm{x-z}_2^{1+\delta}. 
\end{equation*}
In particular, when $\delta=1$, we say $f$ satisfies the quadratic growth (QG) condition. 
\end{defn}

We denote $x^*$ and $ \hat{x}_{nm}$ the optimal solutions to the CSO and the SAA problems, respectively. We are interested in estimating the probability of $\hat x_{nm}$ being an $\eps$-optimal solution to the CSO problem, namely $\PP\left(F(\hat x_{nm})-F(x^*) \leq \eps\right)$, for an arbitrary accuracy $\eps>0$.

Throughout the paper, we assume availability of i.i.d. samples generated from distribution $\PP(\xi)$ and conditional distribution $\PP(\eta\given \xi)$ for any given $\xi$, and we make the following basic assumptions:
\begin{assume}
\label{as:est}
We assume that 
\begin{enumerate}
    \item[(a)] The decision set $\mathcal{X} \subseteq \RR^d$ has a finite diameter $D_\mathcal{X}>0$.
    \item[(b)] $f_\xi(\cdot)$ is $L_f$-Lipschitz continuous and $g_\eta(\cdot,\xi)$ is $L_g$-Lipschitz continuous for any given $\xi$ and $\eta$.
    \item[(c)] For all $x \in\mathcal{X}$, $f(x,\xi)$ is Borel measurable in $\xi$ and $g_\eta(x,\xi)$ is Borel measurable in $\eta$ for all $\xi$.
    \item[(d)] $\sigma_f^2:=\max_{x\in\mathcal{X}} \Var_\xi\left(f_\xi(\EE_{\eta|\xi}[g_\eta(x,\xi)])\right) < \infty$.
    \item[(e)] $\sigma_g^2:=\max_{x\in\mathcal{X}, \xi} \EE_{\eta|\xi}\norm{g_\eta(x,\xi)-{\EE_{\eta|\xi}} g_\eta(x,\xi)}_2^2 < \infty$.
    \item[(f)] $|f_\xi(\cdot)| \leq M_f$, $\|g_\eta(\cdot,\xi)\|_2\leq M_g$ for any $\xi$ and $\eta$.
\end{enumerate}
\end{assume}

\begin{assume}
\label{as:fpl}
The empirical function $\hat F_{nm}(x)$ satisfies the $(\mu,\delta)$-H\"olderian error bound condition with $\mu>0,\delta\geq0$, i.e., it holds that 
\begin{equation*}
\forall x\in \mathcal{X}, \; \hat F_{nm}(x)-\min_{x\in\mathcal{X}}\hat F_{nm}(x) \geq \mu \inf_{z\in\mathcal{X}_{nm}^*}\norm{x-z}_2^{1+\delta}, 
\end{equation*}
where $n,m$ are any positive integers, and $\cX_{nm}^*$ is the optimal solution set of the empirical objective function $\hat F_{nm}(x)$ over $\cX$. 
\end{assume}

\begin{assume}
\label{as:uniquepro}
The empirical function $\hat F_{nm}$ has a unique minimizer $\hat x_{nm}$ on $\mathcal{X}$, for any $n$ and $m$.
\end{assume}

\begin{equation}
\label{biasterm}
    \Delta(m):=
\begin{cases}
\frac{L_f\sigma_{g}}{\sqrt{m}}, &\text{ $f_\xi(\cdot)$ is $L_f$ Lipschitz continuous},\\
\frac{S\sigma_{g}^2}{2m},&\text{$f_\xi(\cdot)$ is additionally $S$ Lipschitz smooth.}
\end{cases}
\end{equation}

