\begin{thm}[SAA under Error Bound Condition]\label{thm:SAA_error_bound}
Under Assumption \ref{as:est}, \ref{as:fpl}, \ref{as:uniquepro}, for any $\eps > 0$, we have
\begin{equation}
\PP (F(\hat x_{nm}) - F(x^*) \geq \eps )
\leq 
\frac{1}{\eps}\bigg(L_f L_g\bigg(\frac{2L_f L_g}{\mu n}\bigg)^{1/\delta}
+
\frac{2L_{f}\sigma_{g}}{\sqrt{m}}\bigg).
\end{equation}

If additionally, $f_\xi(\cdot)$ is $S$-Lipschitz smooth, then we further have 
\begin{equation}
\PP (F(\hat x_{nm}) - F(x^*) \geq \eps )
\leq 
\frac{1}{\eps}\bigg(L_f L_g\bigg(\frac{2L_f L_g}{\mu n}\bigg)^{1/\delta}
+
\frac{S\sigma_{g}^2}{m}\bigg).
\end{equation}
\end{thm}

