proof.raw_tex:
\begin{lm}\label{lm:bias} 
Let $\{\eta_{j}\}_{j=1}^m$ be conditional samples from $P(\eta|\xi)$ given $\xi\sim P(\xi)$. Under Assumption \ref{as:est}, for any fixed $x\in\cX$ that is independent of $\xi$ and $\{\eta_{j}\}_{j=1}^m$, it holds that,
\begin{equation}
\label{eq:lipschitz_bias}
\bigg|\EE_{\{\xi,\{\eta_{j}\}_{j=1}^m \}}\bigg[f_{\xi} \bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{j}}(x,\xi)\bigg)   -   f_{\xi}\big(\EE_{\eta|\xi}g_{\eta}(x,\xi)\big)\bigg]\bigg| \leq \frac{ L_f \sigma_{g}}{\sqrt{m}}.
\end{equation}
If additionally, $f_\xi(\cdot)$ is $S$-Lipschitz smooth, we have
\begin{equation}
\label{eq:smooth_bias}
\bigg|\EE_{\{\xi,\{\eta_{j}\}_{j=1}^m\}} \bigg[f_{\xi} \bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{j}}(x,\xi)\bigg)   -   f_{\xi}\big(\EE_{\eta|\xi}g_{\eta}(x,\xi)\big)\bigg]\bigg|  \leq  \frac{S\sigma_{g}^2}{2m}.
\end{equation}
\end{lm}

\begin{proof}{}
Define $X_{j}: = g_{\eta_{j}}(x,\xi)-\EE_{\eta|\xi}g_{\eta}(x,\xi)$ and $\bar{X}:=\sum_{j=1}^m X_j/m$. It follows  $\EE_{\{\eta_{j}\}_{j=1}^m|\xi}[\bar{X}]=0$ by definition, and $\EE_{\{\eta_{j}\}_{j=1}^m|\xi}[\|\bar{X}\|_2^2]\leq \sigma_g^2/m$ by Assumption \ref{as:est}(d).  $\EE_{\{\eta_{j}\}_{j=1}^m|\xi}  \nabla f_{\xi} \big(\EE_{\eta|\xi}g_{\eta}(x,\xi)\big)^\top \big(\frac{1}{m}\sum_{j=1}^m X_{j}(x)\big)=0$ since $x$ is independent of $\{\eta_j\}_{j=1}^m$. 
The results then follow directly by invoking the Lipschitz continuity and smoothness and taking expectations. 
\end{proof}

\begin{proof} 
Recall that $x^*$ and $\hat x_{nm}$ are the minimizers of $F(x)$ and $\hat F_{nm}(x)$, respectively. It's clear that $x^*$ has no randomness,  and $\hat x_{nm}$ is a function of $\{\xi_i\}_{i =1}^n, \{\eta_{ij}\}_{j=1}^m$. 
We decompose the error $F(\hat x_{nm}) - F(x^*)$ in three terms, and analyze each term below:
\begin{equation*}
\begin{split}
F(\hat x_{nm}) \!-\! F(x^*)
		\!=\!
		\underbrace{F(\hat x_{nm})\!-\! \hat F_{nm}(\hat x_{nm})}_{:=\Epsilon_1}+
		\underbrace{\hat F_{nm}(\hat x_{nm})\! -\! \hat F_{nm}(x^*)}_{:=\Epsilon_2}+
		\underbrace{\hat F_{nm}(x^*)\!- \! F(x^*)}_{:=\Epsilon_3}.
\end{split}
\end{equation*}
First, we use a stability argument and Lemma \ref{lm:bias} to bound $\EE \Epsilon_1 = \EE [F(\hat x_{nm})- \hat F_{nm}(\hat x_{nm})]$. 
Define 
\begin{equation}
\begin{aligned}
\label{eq:Fnmk}
     \hat F_{nm}^{(k)}(x) 
     := \frac{1}{n}\sum_{i\not = k}^n f_{\xi_i}\bigg(\frac{1}{m}\sum_{j =1}^m g_{\eta_{ij}}(x,\xi_i)\bigg) + \frac{1}{n}f_{\xi_k^{\prime}}\bigg(\frac{1}{m}\sum_{j =1}^m g_{\eta_{kj}^{\prime}}(x,\xi_k^{\prime})\bigg)
     \end{aligned}
\end{equation}
as the empirical function by replacing the $k^{th}$ outer sample $\xi_k$ with another i.i.d outer sample $\xi_k^{\prime}$, and replacing the corresponding  inner samples $\{\eta_{kj}\}_{j=1}^m$  with $\{\eta_{kj}^{\prime}\}_{j=1}^m$, which are sampled from the conditional distribution of $\PP(\eta|\xi_k^{\prime})$ for a given sample $\xi_k^\prime$. Denote $\hat x_{nm}^{(k)} := \argmin_{x \in \mathcal{X}} \hat F_{nm}^{(k)}(x)$. We decompose $\EE \Epsilon_1 = \EE [F(\hat x_{nm})- \hat F_{nm}(\hat x_{nm})]$ into three terms:
\begin{equation}\label{eq:decompose_term_1}
\begin{split}
\EE \Epsilon_1 = &\EE\bigg[\frac{1}{n}\sum_{k=1}^n F(\hat x_{nm}) -\frac{1}{n}\sum_{k =1}^n  f_{\xi_k} \bigg( \EE_{\eta|\xi_k} g_\eta(\hat x_{nm}^{(k)},\xi_k) \bigg)\bigg]\\
+&\EE \bigg[\frac{1}{n}\sum_{k =1}^n  f_{\xi_k} \bigg( \EE_{\eta|\xi_k} g_\eta(\hat x_{nm}^{(k)},\xi_k) \bigg) -\frac{1}{n}\sum_{k =1}^n f_{\xi_k}\bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{kj}}(\hat x_{nm}^{(k)},\xi_k)\bigg)\bigg]\\
+&\EE \bigg[\frac{1}{n}\sum_{k =1}^n f_{\xi_k}\bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{kj}}(\hat x_{nm}^{(k)},\xi_k)\bigg) - \hat F_{nm}(\hat x_{nm})\bigg].
\end{split}
\end{equation}
Note that $
    \EE [F(\hat x_{nm})] = \EE [F(\hat x_{nm}^{(k)})]
$ since $\xi_k$ and $\xi_k^{\prime}$ are i.i.d, which implies that  $\hat x_{nm}$ and $\hat x_{nm}^{(k)}$ follow an identical distribution.
Since $\hat x_{nm}^{(k)}$ is independent of $\xi_k$, 
$
\EE [F(\hat x_{nm}^{(k)})] = \EE [f_{\xi_k}(\EE_{\eta|\xi_k}g(\hat x_{nm}^{(k)},\xi_k))]
$
for any $k$. Then the first term in (\ref{eq:decompose_term_1}) is $0$.
As $\hat x_{nm}^{(k)}$ is independent of $\{\eta_{kj}\}_{j=1}^m$, the second term in (\ref{eq:decompose_term_1}) could be bounded by Lemma \ref{lm:bias},
it holds
\begin{equation}
\label{eq:biasboth}
    \EE \bigg[ f_{\xi_k} \bigg( \EE_{\eta|\xi_k} g_\eta(\hat x_{nm}^{(k)},\xi_k) \bigg)  
    -   
    f_{\xi_k}\bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{kj}}(\hat x_{nm}^{(k)},\xi_k) \bigg)\bigg]
    \leq 
    \Delta(m).
\end{equation}
\if 0
for $S$-Lipschitz smooth $f_\xi(\cdot)$, we get
\begin{equation*}
    \EE \bigg[ f_{\xi_k} \bigg( \EE_{\eta|\xi_k} g_\eta(\hat x_{nm}^{(k)},\xi_k) \bigg)  
    -   
    f_{\xi_k}\bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{kj}}(\hat x_{nm}^{(k)},\xi_k) \bigg)\bigg] 
    \leq 
    \frac{S\sigma_{g}^2}{2m}.
\end{equation*}
\fi
For the third term in (\ref{eq:decompose_term_1}), by definition it implies
\begin{equation}
\label{eq:sca1}
    \begin{aligned}
    \hat F_{nm}(\hat x_{nm}^{(k)})  - \hat F_{nm}(\hat x_{nm}) = &\hat F_{nm}^{(k)}(\hat x_{nm}^{(k)})  - \hat F_{nm}^{(k)}(\hat x_{nm}) \\
    + &
      \frac{1}{n}f_{\xi_k}\! \bigg(\! \frac{1}{m}\! \sum_{j =1}^m\!  g_{\eta_{kj}}(\hat x_{nm}^{(k)},\xi_k)\! \bigg) \! 
    - \! \frac{1}{n}f_{\xi_k}\! \bigg(\! \frac{1}{m}\sum_{j =1}^m g_{\eta_{kj}}(\hat x_{nm},\xi_k)\! \bigg)\\
     + &\frac{1}{n}f_{\xi_k^{\prime}}\! \bigg(\! \frac{1}{m}\sum_{j =1}^m g_{\eta_{kj}^{\prime}}(\hat x_{nm},\xi_k^{\prime})\! \bigg) \! 
   \!  - \! 
   \frac{1}{n}f_{\xi_k^{\prime}}\! \bigg(\! \frac{1}{m}\sum_{j =1}^m g_{\eta_{kj}^{\prime}}(\hat x_{nm}^{(k)},\xi_k^{\prime})\! \bigg).
    \end{aligned}
\end{equation}
By Lipschitz continuity of $f_\xi$ and $g_\eta$ and that $\hat F_{nm}^{(k)}(\hat x_{nm}^{(k)})  - \hat F_{nm}^{(k)}(\hat x_{nm}) \leq 0$, it holds
\begin{equation}
\label{eq:sca2}
\hat F_{nm}(\hat x_{nm}^{(k)})  - \hat F_{nm}(\hat x_{nm}) \leq \frac{2}{n}L_f L_g \norm{\hat x_{nm}^{(k)}-\hat x_{nm}}_2.
\end{equation}
Since $\hat x_{nm}$ is the unique minimizer of $\hat F_{nm}(x)$, and $\hat F_{nm}(x)$ satisfies QG condition with parameter $\mu$, we have
\begin{equation}
\label{eq:strong}
    \hat F_{nm}(\hat x_{nm}^{(k)})  - \hat F_{nm}(\hat x_{nm}) \geq \mu \norm{\hat x_{nm}^{(k)}-\hat x_{nm}}_2^{1+\delta}.
\end{equation}
Combining with (\ref{eq:sca2}), we obtain
\begin{equation}
\label{eq:strong2}
\norm{\hat x_{nm}^{(k)}-\hat x_{nm}}_2 \leq \bigg(\frac{2L_f L_g}{\mu n }\bigg)^{1/\delta}.
\end{equation}
By Lipschitz continuity of $f_\xi(\cdot)$ and $g_\eta(\cdot,\xi)$, and definition of $\hat F_{nm}(\hat x_{nm})$, we obtain
\begin{equation}
\label{eq:sca}
\begin{split}
   \EE \bigg[\frac{1}{n}\sum_{k =1}^n f_{\xi_k}\bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{kj}}(\hat x_{nm}^{(k)},\xi_k)\bigg) - \hat F_{nm}(\hat x_{nm})\bigg]
    \leq  L_f L_g\bigg(\frac{2L_f L_g}{\mu n}\bigg)^{1/\delta}.
\end{split}
\end{equation}

Combining (\ref{eq:decompose_term_1}), (\ref{eq:sca}), and (\ref{eq:biasboth}), we obtain
\begin{equation}
\label{eq:scAl}
    \EE \Epsilon_1
    \leq 
    L_f L_g\bigg(\frac{2L_f L_g}{\mu n}\bigg)^{1/\delta}+\Delta(m).
\end{equation}
\if 0
for $L_f$-Lipschitz continuous $f_\xi(\cdot)$,
\begin{equation}
\label{eq:scAl}
    \EE \Epsilon_1
    \leq 
    L_f L_g\bigg(\frac{2L_f L_g}{\mu n}\bigg)^{1/\delta}+\frac{L_{f}\sigma_{g}}{\sqrt{m}};
\end{equation}
for $S$-Lipschitz smooth $f_\xi(\cdot)$,
\begin{equation}
\label{eq:scAs}
    \EE \Epsilon_1
    \leq 
    L_f L_g\bigg(\frac{2L_f L_g}{\mu n}\bigg)^{1/\delta}+\frac{S\sigma_{g}^2}{2m}.
\end{equation}
\fi

Second, by optimality of $\hat x_{nm}$ of $\hat F_{nm}$, we have
\begin{equation}
\label{eq:scB}
    \EE \Epsilon_2 = \EE [\hat F_{nm}(\hat x_{nm})- \hat F_{nm}(x^*)] \leq 0.
\end{equation}

Next, we bound $\EE \Epsilon_3$.
Define
$
\hat{F}_n(x):=\frac{1}{n}\sum_{i=1}^nf_{\xi_i}\big(\EE_{\eta|\xi_i}[g_\eta(x,\xi_i)]\big).
$
Notice that $x^*$ is independent of $\{\eta_{ij}\}_{j=1}^m$ for any $i = \{1,\cdots,n\}$ and $\EE [\hat F_n(x^*) - F(x^*)]=0$. By Lemma \ref{lm:bias}, it holds
\begin{equation}
\label{eq:scC}
    \EE \Epsilon_3 = \EE[ \hat F_{nm}(x^*)-\hat F_n(x) ]+ \EE[\hat F_n(x) - F(x)]
    \leq 
    \Delta(m);
\end{equation}
\if 0
for $L_f$-Lipschitz continuous $f_\xi(\cdot)$,
\begin{equation}
\label{eq:scCL}
    \EE \Epsilon_3 = \EE[ \hat F_{nm}(x^*)-\hat F_n(x) ]+ \EE[\hat F_n(x) - F(x)]
    \leq 
    \frac{L_{f}\sigma_{g}}{\sqrt{m}};
\end{equation}
for $S$-Lipschitz smooth $f_\xi(\cdot)$, we have
\begin{equation}
\label{eq:scCS}
    \EE \Epsilon_3 = \EE[ \hat F_{nm}(x^*)-\hat F_n(x) ]+ \EE[\hat F_n(x) - F(x)]
    \leq 
    \frac{S\sigma_{g}^2}{2m}.
\end{equation}
\fi
Combining (\ref{eq:scAl}), (\ref{eq:scB}), (\ref{eq:scC}), with Markov inequality, we obtain the desired result.
\end{proof}

\begin{proof}{}
Denote $X_{j}(x): = g_{\eta_{j}}(x,\xi)-\EE_{\eta|\xi}g_{\eta}(x,\xi)$, and $\{\eta_{j}\}_{j=1}^m=\{\eta_{1},\cdots, \eta_{m}\}$. By Assumption \ref{as:est},
\begin{equation}
\label{eq:mv}
    \EE_{\{\eta_{j}\}_{j=1}^m|\xi} \bigg(\frac{1}{m}\sum_{j=1}^m X_{j}(x)\bigg)=0, \quad 0 \leq \EE_{\{\eta_{j}\}_{j=1}^m|\xi} \norm{\frac{1}{m}\sum_{j=1}^m X_{j}(x)}_2^2 \leq \frac{\sigma_{g}^2}{m}.
\end{equation}
If $f_\xi(\cdot)$ is $L_f$-Lipschitz continuous,
\begin{equation*}
    \bigg|\EE f_{\xi} \bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{j}}(x,\xi)\bigg)   -   f_{\xi}\bigg(\EE_{\eta|\xi}g_{\eta}(x,\xi)\bigg)\bigg|
    \leq 
    \EE L_f \norm{\frac{1}{m}\sum_{j=1}^m X_{j}(x)}_2 
    \leq 
    \frac{ L_f \sigma_{g}}{\sqrt{m}}.
\end{equation*}
If $f_\xi(\cdot)$ is $S$-Lipschitz smooth,
\begin{equation*}
\begin{aligned}
	&\bigg|f_{\xi} \bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{j}}(x,\xi)\bigg) 
    - f_{\xi}\bigg(\EE_{\eta|\xi}g_{\eta}(x,\xi)\bigg)
