\begin{assume}
\label{as:est}
We assume that 
\begin{enumerate}
    \item[(a)] The decision set $\mathcal{X} \subseteq \RR^d$ has a finite diameter $D_\mathcal{X}>0$.
    \item[(b)] $f_\xi(\cdot)$ is $L_f$-Lipschitz continuous and $g_\eta(\cdot,\xi)$ is $L_g$-Lipschitz continuous for any given $\xi$ and $\eta$.
    \item[(c)] For all $x \in\mathcal{X}$, $f(x,\xi)$ is Borel measurable in $\xi$ and $g_\eta(x,\xi)$ is Borel measurable in $\eta$ for all $\xi$.
    \item[(d)] $\sigma_f^2:=\max_{x\in\mathcal{X}} \Var_\xi\left(f_\xi(\EE_{\eta|\xi}[g_\eta(x,\xi)])\right) < \infty$.
    \item[(e)] $\sigma_g^2:=\max_{x\in\mathcal{X}, \xi} \EE_{\eta|\xi}\norm{g_\eta(x,\xi)-{\EE_{\eta|\xi}} g_\eta(x,\xi)}_2^2 < \infty$.
    \item[(f)] $|f_\xi(\cdot)| \leq M_f$, $\|g_\eta(\cdot,\xi)\|_2\leq M_g$ for any $\xi$ and $\eta$.
\end{enumerate}
\end{assume}

\begin{defn}[H\"olderian error bound  condition]
\label{def:lineq}
Let $f: \mathcal{X} \rightarrow \RR$ be a function with compact domain $\mathcal{X}$ and the optimal solution set $\mathcal{X}^*$ is nonempty. $f(\cdot)$ satisfies the $(\mu,\delta)$-H\"olderian error bound condition if there exists $\delta \geq 0$ and $\mu>0$ such that 
\begin{equation*}
\forall x\in \mathcal{X}, \quad f(x)-\min_{x\in\mathcal{X}}f(x) \geq \mu \inf_{z\in\mathcal{X}^*}\norm{x-z}_2^{1+\delta}. 
\end{equation*}
In particular, when $\delta=1$, we say $f$ satisfies the quadratic growth (QG) condition. 
\end{defn}

\begin{assume}
\label{as:fpl}
The empirical function $\hat F_{nm}(x)$ satisfies the $(\mu,\delta)$-H\"olderian error bound condition with $\mu>0,\delta\geq0$, i.e., it holds that 
\begin{equation*}
\forall x\in \mathcal{X}, \; \hat F_{nm}(x)-\min_{x\in\mathcal{X}}\hat F_{nm}(x) \geq \mu \inf_{z\in\mathcal{X}_{nm}^*}\norm{x-z}_2^{1+\delta}, 
\end{equation*}
where $n,m$ are any positive integers, and $\cX_{nm}^*$ is the optimal solution set of the empirical objective function $\hat F_{nm}(x)$ over $\cX$. 
\end{assume}

\begin{assume}
\label{as:uniquepro}
The empirical function $\hat F_{nm}$ has a unique minimizer $\hat x_{nm}$ on $\mathcal{X}$, for any $n$ and $m$.
\end{assume}

\begin{equation}
\label{biasterm}
    \Delta(m):=
\begin{cases}
\frac{L_f\sigma_{g}}{\sqrt{m}}, &\text{ $f_\xi(\cdot)$ is $L_f$ Lipschitz continuous},\\
\frac{S\sigma_{g}^2}{2m},&\text{$f_\xi(\cdot)$ is additionally $S$ Lipschitz smooth.}
\end{cases}
\end{equation}

\begin{lm}\label{lm:bias} 
Let $\{\eta_{j}\}_{j=1}^m$ be conditional samples from $P(\eta|\xi)$ given $\xi\sim P(\xi)$. Under Assumption \ref{as:est}, for any fixed $x\in\cX$ that is independent of $\xi$ and $\{\eta_{j}\}_{j=1}^m$, it holds that,
\begin{equation}
\label{eq:lipschitz_bias}
\bigg|\EE_{\{\xi,\{\eta_{j}\}_{j=1}^m \}}\bigg[f_{\xi} \bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{j}}(x,\xi)\bigg)   -   f_{\xi}\big(\EE_{\eta|\xi}g_{\eta}(x,\xi)\big)\bigg]\bigg| \leq \frac{ L_f \sigma_{g}}{\sqrt{m}}.
\end{equation}
If additionally, $f_\xi(\cdot)$ is $S$-Lipschitz smooth, we have
\begin{equation}
\label{eq:smooth_bias}
\bigg|\EE_{\{\xi,\{\eta_{j}\}_{j=1}^m\}} \bigg[f_{\xi} \bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{j}}(x,\xi)\bigg)   -   f_{\xi}\big(\EE_{\eta|\xi}g_{\eta}(x,\xi)\big)\bigg]\bigg|  \leq  \frac{S\sigma_{g}^2}{2m}.
\end{equation}
\end{lm}

\begin{proof}{}
Define $X_{j}: = g_{\eta_{j}}(x,\xi)-\EE_{\eta|\xi}g_{\eta}(x,\xi)$ and $\bar{X}:=\sum_{j=1}^m X_j/m$. It follows  $\EE_{\{\eta_{j}\}_{j=1}^m|\xi}[\bar{X}]=0$ by definition, and $\EE_{\{\eta_{j}\}_{j=1}^m|\xi}[\|\bar{X}\|_2^2]\leq \sigma_g^2/m$ by Assumption \ref{as:est}(d).  $\EE_{\{\eta_{j}\}_{j=1}^m|\xi}  \nabla f_{\xi} \big(\EE_{\eta|\xi}g_{\eta}(x,\xi)\big)^\top \big(\frac{1}{m}\sum_{j=1}^m X_{j}(x)\big)=0$ since $x$ is independent of $\{\eta_j\}_{j=1}^m$. 
The results then follow directly by invoking the Lipschitz continuity and smoothness and taking expectations. 
\end{proof}

\begin{proof}{}
Denote $X_{j}(x): = g_{\eta_{j}}(x,\xi)-\EE_{\eta|\xi}g_{\eta}(x,\xi)$, and $\{\eta_{j}\}_{j=1}^m=\{\eta_{1},\cdots, \eta_{m}\}$. By Assumption \ref{as:est},
\begin{equation}
\label{eq:mv}
    \EE_{\{\eta_{j}\}_{j=1}^m|\xi} \bigg(\frac{1}{m}\sum_{j=1}^m X_{j}(x)\bigg)=0, \quad 0 \leq \EE_{\{\eta_{j}\}_{j=1}^m|\xi} \norm{\frac{1}{m}\sum_{j=1}^m X_{j}(x)}_2^2 \leq \frac{\sigma_{g}^2}{m}.
\end{equation}
If $f_\xi(\cdot)$ is $L_f$-Lipschitz continuous,
\begin{equation*}
    \bigg|\EE f_{\xi} \bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{j}}(x,\xi)\bigg)   -   f_{\xi}\bigg(\EE_{\eta|\xi}g_{\eta}(x,\xi)\bigg)\bigg|
    \leq 
    \EE L_f \norm{\frac{1}{m}\sum_{j=1}^m X_{j}(x)}_2 
    \leq 
    \frac{ L_f \sigma_{g}}{\sqrt{m}}.
\end{equation*}
If $f_\xi(\cdot)$ is $S$-Lipschitz smooth,
\begin{equation*}
\begin{aligned}
	&\bigg|f_{\xi} \bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{j}}(x,\xi)\bigg) 
    - f_{\xi}\bigg(\EE_{\eta|\xi}g_{\eta}(x,\xi)\bigg)
    - \nabla f_{\xi} \bigg(\EE_{\eta|\xi}g_{\eta}(x,\xi)\bigg)^\top \frac{1}{m}\sum_{j=1}^m X_{j}(x)\bigg| \\
    \leq &\frac{S}{2} \norm{\frac{1}{m}\sum_{j=1}^m X_{j}(x)}_2^2.
    \end{aligned}
\end{equation*}
$\EE_{\{\eta_{j}\}_{j=1}^m|\xi}  \nabla f_{\xi} \big(\EE_{\eta|\xi}g_{\eta}(x,\xi)\big)^\top \big(\frac{1}{m}\sum_{j=1}^m X_{j}(x)\big)=0$ since $x$ is independent of ${\eta}_{j=1}^m$, we obtain,
\begin{equation*}
    \EE   f_{\xi} \bigg(\frac{1}{m}\sum_{j=1}^m g_{\eta_{j}}(x,\xi)\bigg)   -   f_{\xi}\bigg(\EE_{\eta|\xi}g_{\eta}(x,\xi)\bigg)
    \leq 
    \EE \bigg[ \frac{S}{2} \norm{\frac{1}{m}\sum_{j=1}^m X_{j}(x)}_2^2 \bigg] \\
    \leq  
    \frac{S\sigma_{g}^2}{2m}.
\end{equation*}
For the other side, we could derive a similar lower bound. As a result, (\ref{eq:smooth_bias}) holds.
\end{proof}

